    try (NameServer server = new NameServerImpl(0, factory)) {
        int serverPort = server.getPort();
        try (NameClient client = new NameClient(NetUtils.getLocalAddress(), serverPort, factory, retryCount, retryTimeout, new NameCache(10000))) {
