        client.register(id, idToAddrMap.get(id));
    }
    // wait
    final Set<Identifier> ids = idToAddrMap.keySet();
    busyWait(server, ids.size(), ids);
    // lookup
    final Identifier id1 = this.factory.getNewInstance("task1");
