    for (int size : messageSizes) {
        final int numMessages = 300000 / (Math.max(1, size / 512));
        int numThreads = 2;
        int totalNumMessages = numMessages * numThreads;
        final Monitor monitor = new Monitor();
        LOG.log(Level.FINEST, "=== Test network service receiver start");
        // network service
        final String name2 = "task2";
        NetworkService<String> ns2 = new NetworkService<String>(factory, 0, nameServerAddr, nameServerPort, new StringCodec(), new MessagingTransportFactory(), new MessageHandler<String>(name2, monitor, totalNumMessages), new ExceptionHandler());
        ns2.registerId(factory.getNewInstance(name2));
        final int port2 = ns2.getTransport().getListeningPort();
        server.register(factory.getNewInstance("task2"), new InetSocketAddress(nameServerAddr, port2));
        LOG.log(Level.FINEST, "=== Test network service sender start");
        final String name1 = "task1";
        NetworkService<String> ns1 = new NetworkService<String>(factory, 0, nameServerAddr, nameServerPort, new StringCodec(), new MessagingTransportFactory(), new MessageHandler<String>(name1, null, 0), new ExceptionHandler());
        ns1.registerId(factory.getNewInstance(name1));
        final int port1 = ns1.getTransport().getListeningPort();
        server.register(factory.getNewInstance("task1"), new InetSocketAddress(nameServerAddr, port1));
        Identifier destId = factory.getNewInstance(name2);
        final Connection<String> conn = ns1.newConnection(destId);
        conn.open();
        // build the message
        StringBuilder msb = new StringBuilder();
        for (int i = 0; i < size; i++) {
            msb.append("1");
        }
        final String message = msb.toString();
        ExecutorService e = Executors.newCachedThreadPool();
        long start = System.currentTimeMillis();
        for (int i = 0; i < numThreads; i++) {
            e.submit(new Runnable() {

                @Override
                public void run() {
                    try {
                        for (int i = 0; i < numMessages; i++) {
                            conn.write(message);
                        }
                    } catch (NetworkException e) {
                        e.printStackTrace();
                    }
                }
            });
        }
        e.shutdown();
        e.awaitTermination(30, TimeUnit.SECONDS);
        monitor.mwait();
        long end = System.currentTimeMillis();
        double runtime = ((double) end - start) / 1000;
        // x2 for unicode chars
        LOG.log(Level.FINEST, "size: " + size + "; messages/s: " + totalNumMessages / runtime + " bandwidth(bytes/s): " + ((double) totalNumMessages * 2 * size) / runtime);
        conn.close();
        ns1.close();
        ns2.close();
    }
    server.close();
}

/**
 * NetworkService messaging rate benchmark
 */
@Test
public void testMessagingNetworkServiceBatchingRate() throws Exception {
    LOG.log(Level.FINEST, name.getMethodName());
    IdentifierFactory factory = new StringIdentifierFactory();
    String nameServerAddr = NetUtils.getLocalAddress();
    NameServer server = new NameServerImpl(0, factory);
    int nameServerPort = server.getPort();
    final int batchSize = 1024 * 1024;
    final int[] messageSizes = { 32, 64, 512 };
    for (int size : messageSizes) {
        final int numMessages = 300 / (Math.max(1, size / 512));
        final Monitor monitor = new Monitor();
        LOG.log(Level.FINEST, "=== Test network service receiver start");
        // network service
        final String name2 = "task2";
        NetworkService<String> ns2 = new NetworkService<String>(factory, 0, nameServerAddr, nameServerPort, new StringCodec(), new MessagingTransportFactory(), new MessageHandler<String>(name2, monitor, numMessages), new ExceptionHandler());
        ns2.registerId(factory.getNewInstance(name2));
        final int port2 = ns2.getTransport().getListeningPort();
        server.register(factory.getNewInstance("task2"), new InetSocketAddress(nameServerAddr, port2));
        LOG.log(Level.FINEST, "=== Test network service sender start");
        final String name1 = "task1";
        NetworkService<String> ns1 = new NetworkService<String>(factory, 0, nameServerAddr, nameServerPort, new StringCodec(), new MessagingTransportFactory(), new MessageHandler<String>(name1, null, 0), new ExceptionHandler());
        ns1.registerId(factory.getNewInstance(name1));
        final int port1 = ns1.getTransport().getListeningPort();
        server.register(factory.getNewInstance("task1"), new InetSocketAddress(nameServerAddr, port1));
        Identifier destId = factory.getNewInstance(name2);
        Connection<String> conn = ns1.newConnection(destId);
        // build the message
        StringBuilder msb = new StringBuilder();
        for (int i = 0; i < size; i++) {
            msb.append("1");
        }
        String message = msb.toString();
        long start = System.currentTimeMillis();
        try {
            for (int i = 0; i < numMessages; i++) {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < batchSize / size; j++) {
                    sb.append(message);
                }
                conn.open();
                conn.write(sb.toString());
            }
            monitor.mwait();
        } catch (NetworkException e) {
            e.printStackTrace();
        }
        long end = System.currentTimeMillis();
        double runtime = ((double) end - start) / 1000;
        long numAppMessages = numMessages * batchSize / size;
        // x2 for unicode chars
        LOG.log(Level.FINEST, "size: " + size + "; messages/s: " + numAppMessages / runtime + " bandwidth(bytes/s): " + ((double) numAppMessages * 2 * size) / runtime);
        conn.close();
        ns1.close();
        ns2.close();
    }
    server.close();
}

