    final Injector injector1 = Tang.Factory.getTang().newInjector(httpRuntimeConfiguration);
    final HttpServer httpServer1 = injector1.getInstance(HttpServer.class);
    final String portUsed = "" + httpServer1.getPort();
    final Configuration httpServerConfiguration = Tang.Factory.getTang().newConfigurationBuilder().bindNamedParameter(PortNumber.class, portUsed).bindNamedParameter(MaxPortNumber.class, portUsed).bindNamedParameter(MinPortNumber.class, portUsed).bindNamedParameter(MaxRetryAttempts.class, "3").build();
    final Configuration configuration = Configurations.merge(httpRuntimeConfiguration, httpServerConfiguration);
    final Injector injector2 = Tang.Factory.getTang().newInjector(configuration);
    try {
        injector2.getInstance(HttpServer.class);
        Assert.fail("Created two web servers on the same port: " + portUsed);
